"use strict";(self.webpackChunkchatgpt_shortcut=self.webpackChunkchatgpt_shortcut||[]).push([["9493"],{87551(n){n.exports=JSON.parse('{"id":11652,"title":"\u300AJournal of Chemical Education\u300B\u671F\u520A\u8BBA\u6587\u64B0\u5199\u8981\u6C42","description":"# \u8BBA\u6587\u64B0\u5199\u6307\u4EE4\uFF1A\u300AJournal of Chemical Education\u300B\u671F\u520A\u8BBA\u6587\u64B0\u5199\u8981\u6C42\\n## \u4E00\u3001\u6838\u5FC3\u64B0\u5199\u4F9D\u636E\\n\u672C\u8BBA\u6587\u64B0\u5199\u4EE5**\u4F60\u63D0\u4F9B\u7684\u8BBA\u6587\u57FA\u672C\u601D\u8DEF**\u4E3A\u6838\u5FC3\u6846\u67B6\uFF0C\u7ED3\u5408\u300AJournal of Chemical Education\u300B\u671F\u520A\u683C\u5F0F\u89C4\u8303\u3001\u5B9E\u9A8C\u6559\u5B66\u7C7B\u8BBA\u6587\u521B\u4F5C\u8981\u6C42\uFF0C\u4EE5\u53CA\u4E0A\u4F20\u7684\u819C\u5206\u79BB\u5B9E\u9A8C\u76F8\u5173\u8BBA\u6587\u3001\u5B66\u751F\u624B\u518C\u3001\u6559\u5E08\u6307\u5357\u7B49\u53C2\u8003\u6750\u6599\u4E3A\u683C\u5F0F\u4E0E\u5185\u5BB9\u8303\u672C\uFF0C\u5B8C\u6210\u4E00\u7BC7\u7B26\u5408\u671F\u520A\u53D1\u8868\u6807\u51C6\u3001\u517C\u5177**\u79D1\u7814\u6027\u4E0E\u6559\u5B66\u6027**\u7684\u5316\u5B66\u6559\u80B2\u7C7B\u5B9E\u9A8C\u5BA4\u5B9E\u9A8C\u8BBA\u6587\u3002\\n\\n## \u4E8C\u3001\u671F\u520A\u6838\u5FC3\u683C\u5F0F\u9075\u5FAA\\n\u4E25\u683C\u6309\u7167\u300AJournal of Chemical Education\u300B\uFF08ACS\u65D7\u4E0B\u671F\u520A\uFF09\u5B9E\u9A8C\u6559\u5B66\u7C7B\u8BBA\u6587\u56FA\u5B9A\u683C\u5F0F\u64B0\u5199\uFF0C\u6574\u4F53\u7ED3\u6784\u4E3A**\u9876\u90E8\u6807\u8BC6\u4FE1\u606F\u2192\u6807\u9898\u2192\u4F5C\u8005\u4E0E\u5355\u4F4D\u2192\u6458\u8981&\u5173\u952E\u8BCD\u2192\u6B63\u6587\u6838\u5FC3\u7AE0\u8282\u2192ASSOCIATED CONTENT\u2192AUTHOR INFORMATION\u2192ACKNOWLEDGMENTS\u2192REFERENCES**\uFF0C\u540C\u65F6\u6EE1\u8DB3\u4EE5\u4E0B\u683C\u5F0F\u7EC6\u8282\uFF1A\\n1. \u6807\u9898\uFF1A\u5B9E\u8BCD\u9996\u5B57\u6BCD\u5927\u5199\u3001\u865A\u8BCD\u5C0F\u5199\uFF0C\u52A0\u7C97\u5C45\u4E2D\uFF0C\u7B80\u6D01\u4F53\u73B0\u201C\u5B9E\u9A8C\u6280\u672F/\u5185\u5BB9+\u6559\u5B66\u5E94\u7528+\u7814\u7A76\u5BF9\u8C61\u201D\uFF0C\u63A7\u52361-2\u884C\uFF1B\\n2. \u4F5C\u8005\u4E0E\u5355\u4F4D\uFF1A\u59D3\u540D\u4E3A\u201C\u540D\u5168\u62FC+\u59D3\u5168\u62FC\u201D\uFF0C\u901A\u8BAF\u4F5C\u8005\u52A0*\u6807\u6CE8\uFF0C\u5355\u4F4D\u7528\u6570\u5B57\u4E0A\u6807\u5BF9\u5E94\uFF0C\u5305\u542B\u201C\u5B9E\u9A8C\u5BA4/\u7814\u7A76\u4E2D\u5FC3\u2192\u5B66\u9662\u2192\u5B66\u6821\u2192\u57CE\u5E02\u2192\u90AE\u7F16\u2192\u56FD\u5BB6\u201D\uFF0C\u901A\u8BAF\u4F5C\u8005\u6807\u6CE8\u90AE\u7BB1\uFF0C\u53EF\u9009ORCID\uFF1B\\n3. \u5B57\u4F53\u4E0E\u6392\u7248\uFF1A\u6B63\u6587\u91C7\u7528Times New Roman 10-12\u53F7\u5B57\uFF0C\u5355\u500D\u884C\u8DDD\uFF0C\u6BB5\u9996\u65E0\u7F29\u8FDB\uFF1B\u4E00\u7EA7\u6807\u9898\u5168\u5927\u5199\u3001\u52A0\u7C97\u3001\u5DE6\u5BF9\u9F50\uFF0C\u4E8C\u7EA7\u6807\u9898\u9996\u5B57\u6BCD\u5927\u5199\u3001\u659C\u4F53\uFF0C\u4E09\u7EA7\u6807\u9898\u4EC5\u9996\u5B57\u6BCD\u5927\u5199\u3001\u65E0\u683C\u5F0F\uFF1B\\n4. \u56FE\u8868\u4E0E\u516C\u5F0F\uFF1A\u56FE\u8868\u968F\u6587\u51FA\u73B0\uFF0C\u6B63\u520A\u56FE\u8868\u7F16\u53F7\u4E3AFigure X/Table X\uFF0C\u516C\u5F0F\u5C45\u4E2D\u6392\u5217\u3001\u53D8\u91CF\u659C\u4F53\u3001\u5355\u4F4D\u6B63\u4F53\uFF0C\u6807\u6CE8\u56FD\u9645\u6807\u51C6\u5355\u4F4D\uFF0C\u590D\u5408\u5355\u4F4D\u7528\u4E2D\u95F4\u70B9\u8FDE\u63A5\uFF1B\\n5. \u7F29\u5199\u4E0E\u6807\u6CE8\uFF1A\u4E13\u4E1A\u672F\u8BED\u9996\u6B21\u51FA\u73B0\u6807\u6CE8\u201C\u5168\u79F0+\u7F29\u5199\u201D\uFF0C\u5316\u5B66\u54C1\u53EF\u9009\u6807\u6CE8CAS\u53F7\uFF0C\u5B9E\u9A8C\u53C2\u6570\u660E\u786E\u6807\u6CE8\u5173\u952E\u6570\u503C\uFF08\u5982\u53CD\u5E94\u65F6\u95F4\u3001\u6709\u6548\u9762\u79EF\u3001\u6D53\u5EA6\u7B49\uFF09\u3002\\n\\n## \u4E09\u3001\u8BBA\u6587\u4E3B\u4F53\u5185\u5BB9\u8981\u6C42\\n\u672C\u8BBA\u6587\u4E3A**\u5B9E\u9A8C\u5BA4\u5B9E\u9A8C\u6559\u5B66\u7C7B\u8BBA\u6587**\uFF0C\u9700\u7A81\u51FA\u5316\u5B66\u6559\u80B2\u5C5E\u6027\uFF0C\u517C\u987E\u79D1\u7814\u4E25\u8C28\u6027\u4E0E\u6559\u5B66\u5B9E\u7528\u6027\uFF0C\u6B63\u6587\u6838\u5FC3\u7AE0\u8282\u6309\u4EE5\u4E0B\u903B\u8F91\u64B0\u5199\uFF0C\u5404\u7AE0\u8282\u5185\u5BB9\u9700\u7D27\u6263\u4F60\u7684\u8BBA\u6587\u57FA\u672C\u601D\u8DEF\u5C55\u5F00\uFF0C\u53C2\u8003\u6750\u6599\u4EC5\u4F5C\u683C\u5F0F\u4E0E\u5185\u5BB9\u6846\u67B6\u8303\u672C\uFF0C\u4E0D\u5F97\u6284\u88AD\uFF1A\\n### 1. INTRODUCTION\uFF08\u5F15\u8A00\uFF09\\n1. \u9610\u8FF0\u7814\u7A76\u80CC\u666F\uFF08\u8D34\u5408\u8BBA\u6587\u4E3B\u9898\u7684\u884C\u4E1A/\u5B66\u79D1\u95EE\u9898\uFF0C\u5982\u6C61\u67D3\u7269\u5904\u7406\u3001\u6750\u6599\u5408\u6210\u3001\u5206\u6790\u68C0\u6D4B\u7B49\u9886\u57DF\u7684\u5B9E\u9645\u9700\u6C42\uFF09\uFF1B\\n2. \u6307\u51FA\u5F53\u524D\u672C\u79D1\u76F8\u5173\u5B9E\u9A8C\u6559\u5B66\u7684\u75DB\u70B9\uFF08\u5982\u4EC5\u4F7F\u7528\u5546\u7528\u8BD5\u5242/\u5668\u6750\u3001\u7F3A\u4E4F\u81EA\u4E3B\u5236\u5907\u73AF\u8282\u3001\u7406\u8BBA\u4E0E\u5B9E\u8DF5\u8131\u8282\u7B49\uFF09\uFF1B\\n3. \u8BF4\u660E\u672C\u5B9E\u9A8C\u7684\u521B\u65B0\u70B9\uFF08\u5982\u5B9E\u9A8C\u65B9\u6CD5\u3001\u6750\u6599\u5236\u5907\u3001\u8868\u5F81\u6D4B\u8BD5\u624B\u6BB5\u7684\u7279\u8272\uFF09\u4E0E\u6559\u5B66\u610F\u4E49\uFF08\u5982\u57F9\u517B\u5B66\u751F\u7684\u79D1\u7814\u601D\u7EF4\u3001\u5B9E\u9A8C\u64CD\u4F5C\u80FD\u529B\u3001\u8DE8\u5B66\u79D1\u5E94\u7528\u80FD\u529B\u7B49\uFF09\uFF1B\\n4. \u7B80\u8981\u6982\u8FF0\u8BBA\u6587\u6838\u5FC3\u5185\u5BB9\uFF0C\u5F15\u51FA\u5B9E\u9A8C\u8BBE\u8BA1\u601D\u8DEF\u3002\\n\\n### 2. STUDENT LEARNING OBJECTIVES\uFF08\u5B66\u751F\u5B66\u4E60\u76EE\u6807\uFF09\\n\u52063\u7C7B\u660E\u786E\u672C\u79D1\u5B66\u751F\u901A\u8FC7\u672C\u5B9E\u9A8C\u9700\u638C\u63E1\u7684\u80FD\u529B\uFF0C\u8D34\u5408\u8BBA\u6587\u4E3B\u9898\u4E0E\u5B9E\u9A8C\u96BE\u5EA6\uFF0C\u6BCF\u7C7B\u76EE\u6807\u8868\u8FF0\u5177\u4F53\u3001\u53EF\u843D\u5730\uFF1A\\n1. \u539F\u7406\u7406\u89E3\uFF1A\u638C\u63E1\u5B9E\u9A8C\u76F8\u5173\u7684\u6838\u5FC3\u5316\u5B66/\u6750\u6599/\u5DE5\u7A0B\u539F\u7406\u3001\u5B9E\u9A8C\u65B9\u6CD5\u7684\u57FA\u672C\u7406\u8BBA\u3001\u5206\u79BB/\u5408\u6210/\u8868\u5F81\u7684\u6838\u5FC3\u673A\u5236\uFF1B\\n2. \u5B9E\u9A8C\u6280\u80FD\uFF1A\u638C\u63E1\u5B9E\u9A8C\u6240\u9700\u7684\u4EEA\u5668\u64CD\u4F5C\u3001\u6837\u54C1\u5236\u5907\u3001\u6570\u636E\u6D4B\u8BD5\u4E0E\u5206\u6790\u65B9\u6CD5\uFF0C\u5B66\u4F1A\u5B9E\u9A8C\u88C5\u7F6E\u7684\u7EC4\u88C5\u4E0E\u8C03\u8BD5\uFF1B\\n3. \u5E94\u7528\u62D3\u5C55\uFF1A\u7406\u89E3\u5B9E\u9A8C\u6210\u679C\u5728\u5B9E\u9645\u9886\u57DF\u7684\u5E94\u7528\u4EF7\u503C\uFF0C\u57F9\u517B\u79D1\u5B66\u63A2\u7A76\u80FD\u529B\u3001\u6570\u636E\u5206\u6790\u80FD\u529B\u4E0E\u56E2\u961F\u534F\u4F5C\u80FD\u529B\u3002\\n\\n### 3. PEDAGOGICAL OBJECTIVES\uFF08\u6559\u5B66\u76EE\u6807\uFF09\\n\u7ED3\u5408\u672C\u79D1\u5316\u5B66/\u6750\u6599/\u5316\u5DE5\u7B49\u4E13\u4E1A\u7684\u6559\u5B66\u8981\u6C42\uFF0C\u8BF4\u660E\u672C\u5B9E\u9A8C\u7684\u6559\u5B66\u4EF7\u503C\uFF0C\u91CD\u70B9\u7A81\u51FA\uFF1A\\n1. \u5B9E\u73B0\u201C\u7406\u8BBA\u77E5\u8BC6\u4E0E\u5B9E\u9A8C\u5B9E\u8DF5\u201D\u7684\u7ED3\u5408\uFF0C\u5F25\u8865\u4F20\u7EDF\u6559\u5B66\u7684\u4E0D\u8DB3\uFF1B\\n2. \u57F9\u517B\u5B66\u751F\u7684\u57FA\u7840\u79D1\u7814\u7D20\u517B\uFF08\u5982\u5B9E\u9A8C\u8BBE\u8BA1\u3001\u73B0\u8C61\u89C2\u5BDF\u3001\u6570\u636E\u8BB0\u5F55\u4E0E\u5206\u6790\u3001\u7ED3\u679C\u8BA8\u8BBA\uFF09\uFF1B\\n3. \u63D0\u5347\u5B66\u751F\u5BF9\u76F8\u5173\u5B66\u79D1\u9886\u57DF\u7684\u5B66\u4E60\u5174\u8DA3\uFF0C\u4E3A\u540E\u7EED\u4E13\u4E1A\u5B66\u4E60\u4E0E\u79D1\u7814\u6253\u4E0B\u57FA\u7840\u3002\\n\\n### 4. PROCEDURE\uFF08\u5B9E\u9A8C\u6D41\u7A0B\uFF09\\n\u52063\u4E2A\u5B50\u6A21\u5757\u64B0\u5199\uFF0C\u5185\u5BB9\u6B65\u9AA4\u5316\u3001\u53C2\u6570\u660E\u786E\uFF0C\u53EF\u76F4\u63A5\u7528\u4E8E\u672C\u79D1\u5B9E\u9A8C\u5BA4\u6559\u5B66\uFF0C\u65E0\u6A21\u7CCA\u8868\u8FF0\uFF1A\\n1. Equipment and Chemicals\uFF1A\u5206\u7C7B\u5217\u51FA\u5B9E\u9A8C\u6240\u9700**\u4EEA\u5668\uFF08\u542B\u578B\u53F7\u3001\u4EA7\u5730\u53EF\u9009\uFF09\u3001\u8BD5\u5242\uFF08\u542B\u7EAF\u5EA6\u3001\u6D53\u5EA6\u3001\u7528\u91CF\uFF0C\u6807\u6CE8\u4F9B\u5E94\u5546\u53EF\u9009\uFF09\u3001\u8017\u6750**\uFF0C\u6309\u5B9E\u9A8C\u4F7F\u7528\u9891\u7387\u6392\u5E8F\uFF1B\\n2. Experiment Overview\uFF1A\u7B80\u8981\u6982\u8FF0\u5B9E\u9A8C\u6574\u4F53\u6D41\u7A0B\uFF0C\u5206\u9636\u6BB5\u8BF4\u660E\u5B9E\u9A8C\u6838\u5FC3\u73AF\u8282\uFF08\u5982\u6837\u54C1\u5236\u5907\u2192\u8868\u5F81\u6D4B\u8BD5\u2192\u6027\u80FD\u9A8C\u8BC1\uFF09\uFF0C\u660E\u786E\u5B9E\u9A8C\u5206\u7EC4\u3001\u64CD\u4F5C\u65F6\u957F\u7B49\u6559\u5B66\u76F8\u5173\u4FE1\u606F\uFF1B\\n3. HAZARDS\uFF1A\u5355\u72EC\u5217\u51FA\u5B9E\u9A8C\u6D89\u53CA\u7684\u5371\u9669\u5316\u5B66\u54C1/\u64CD\u4F5C\u7684\u5B89\u5168\u6CE8\u610F\u4E8B\u9879\uFF0C\u660E\u786E**\u5316\u5B66\u54C1\u5371\u5BB3\uFF08\u5982\u8150\u8680\u6027\u3001\u523A\u6FC0\u6027\u3001\u6BD2\u6027\uFF09\u3001\u9632\u62A4\u63AA\u65BD\uFF08\u5982\u4F69\u6234PPE\u3001\u5728\u901A\u98CE\u6A71\u64CD\u4F5C\uFF09\u3001\u5E94\u6025\u5904\u7406\u65B9\u6CD5\uFF08\u5982\u76AE\u80A4\u63A5\u89E6\u3001\u773C\u775B\u63A5\u89E6\u7684\u5904\u7406\u65B9\u5F0F\uFF09\u3001\u5E9F\u6DB2/\u56FA\u5E9F\u5904\u7406\u8981\u6C42**\u3002\\n\\n### 5. RESULTS AND DISCUSSION\uFF08\u7ED3\u679C\u4E0E\u8BA8\u8BBA\uFF09\\n\u672C\u7AE0\u8282\u4E3A\u8BBA\u6587\u6838\u5FC3\uFF0C\u9700\u7ED3\u5408\u5B9E\u9A8C\u6570\u636E\u3001\u56FE\u8868\u8FDB\u884C\u5206\u6790\uFF0C\u517C\u987E**\u79D1\u7814\u7ED3\u679C\u89E3\u8BFB**\u4E0E**\u6559\u5B66\u89C2\u5BDF\u53CD\u9988**\uFF0C\u903B\u8F91\u6E05\u6670\uFF1A\\n1. \u5B9E\u9A8C\u73B0\u8C61\u4E0E\u57FA\u7840\u7ED3\u679C\uFF1A\u63CF\u8FF0\u5B9E\u9A8C\u8FC7\u7A0B\u4E2D\u7684\u5173\u952E\u73B0\u8C61\uFF08\u5982\u6837\u54C1\u5236\u5907\u4E2D\u7684\u5F62\u6001\u53D8\u5316\u3001\u53CD\u5E94\u754C\u9762\u7684\u7279\u5F81\u3001\u6D4B\u8BD5\u4E2D\u7684\u76F4\u89C2\u7ED3\u679C\uFF09\uFF0C\u7528\u56FE\u8868\u5448\u73B0\u6838\u5FC3\u6570\u636E\uFF08\u5982\u8868\u5F81\u56FE\u8C31\u3001\u6027\u80FD\u6D4B\u8BD5\u66F2\u7EBF\u3001\u6D53\u5EA6/\u6548\u7387\u53D8\u5316\u6570\u636E\uFF09\uFF1B\\n2. \u7ED3\u679C\u5206\u6790\uFF1A\u7ED3\u5408\u76F8\u5173\u7406\u8BBA\uFF0C\u89E3\u91CA\u5B9E\u9A8C\u73B0\u8C61\u4E0E\u6570\u636E\u80CC\u540E\u7684\u539F\u7406\uFF0C\u5206\u6790\u5B9E\u9A8C\u5173\u952E\u53C2\u6570\u5BF9\u7ED3\u679C\u7684\u5F71\u54CD\uFF0C\u8BF4\u660E\u5B9E\u9A8C\u7684\u79D1\u5B66\u6027\u4E0E\u5408\u7406\u6027\uFF1B\\n3. \u6559\u5B66\u89C6\u89D2\u5206\u6790\uFF1A\u4ECE\u672C\u79D1\u6559\u5B66\u89D2\u5EA6\uFF0C\u8BF4\u660E\u5B66\u751F\u5728\u5B9E\u9A8C\u64CD\u4F5C\u4E2D\u6613\u51FA\u73B0\u7684\u95EE\u9898\u3001\u5173\u952E\u64CD\u4F5C\u7684\u6CE8\u610F\u4E8B\u9879\u3001\u5B9E\u9A8C\u73B0\u8C61\u5BF9\u5B66\u751F\u7406\u89E3\u7406\u8BBA\u77E5\u8BC6\u7684\u5E2E\u52A9\uFF1B\\n4. \u5BF9\u6BD4\u5206\u6790\uFF08\u53EF\u9009\uFF09\uFF1A\u82E5\u6709\u5BF9\u7167\u7EC4\u5B9E\u9A8C\uFF08\u5982\u4E0D\u540C\u53C2\u6570\u3001\u4E0D\u540C\u6750\u6599\u3001\u5546\u7528\u5668\u6750vs\u81EA\u4E3B\u5236\u5907\uFF09\uFF0C\u9700\u5BF9\u6BD4\u5206\u6790\u7ED3\u679C\u5DEE\u5F02\uFF0C\u8BF4\u660E\u672C\u5B9E\u9A8C\u8BBE\u8BA1\u7684\u4F18\u52BF\u3002\\n\\n### 6. STUDENTS\u2019 EXPERIENCE AND FEEDBACK\uFF08\u5B66\u751F\u4F53\u9A8C\u4E0E\u53CD\u9988\uFF09\\n\u7ED3\u5408\u672C\u79D1\u5B9E\u9A8C\u6559\u5B66\u7684\u5B9E\u9645\u5F00\u5C55\u60C5\u51B5\u64B0\u5199\uFF0C\u5185\u5BB9\u771F\u5B9E\u3001\u8D34\u5408\u6559\u5B66\u5B9E\u9645\uFF0C\u5305\u542B\uFF1A\\n1. \u5B9E\u9A8C\u5F00\u5C55\u5B89\u6392\uFF1A\u8BF4\u660E\u5B9E\u9A8C\u7684\u8BFE\u65F6\u5206\u914D\u3001\u5B66\u751F\u5206\u7EC4\u65B9\u5F0F\u3001\u6559\u5B66\u5B9E\u65BD\u6D41\u7A0B\uFF08\u5982\u7406\u8BBA\u8BB2\u89E3\u2192\u6559\u5E08\u6F14\u793A\u2192\u5B66\u751F\u81EA\u4E3B\u64CD\u4F5C\u2192\u6570\u636E\u6574\u7406\u2192\u7ED3\u679C\u8BA8\u8BBA\uFF09\uFF1B\\n2. \u5B66\u751F\u64CD\u4F5C\u7ED3\u679C\uFF1A\u63CF\u8FF0\u5B66\u751F\u5B8C\u6210\u5B9E\u9A8C\u7684\u6574\u4F53\u60C5\u51B5\uFF08\u5982\u5B9E\u9A8C\u6210\u529F\u7387\u3001\u6570\u636E\u51C6\u786E\u6027\u3001\u64CD\u4F5C\u89C4\u8303\u6027\uFF09\uFF0C\u5206\u6790\u5B66\u751F\u64CD\u4F5C\u4E2D\u5B58\u5728\u7684\u5171\u6027\u95EE\u9898\u4E0E\u89E3\u51B3\u65B9\u6CD5\uFF1B\\n3. \u5B66\u751F\u53CD\u9988\u8C03\u67E5\uFF1A\u8BBE\u8BA1\u7B80\u5355\u7684\u53CD\u9988\u95EE\u5377\uFF08\u53C2\u8003\u8303\u672C\u4E2D\u76845\u5206\u5236\u8BC4\u5206\u8868\uFF09\uFF0C\u56F4\u7ED5\u201C\u5B9E\u9A8C\u539F\u7406\u7406\u89E3\u3001\u5B9E\u9A8C\u8DA3\u5473\u6027\u3001\u64CD\u4F5C\u6307\u5F15\u6E05\u6670\u5EA6\u3001\u80FD\u529B\u63D0\u5347\u6548\u679C\u201D\u7B49\u7EF4\u5EA6\u8BBE\u7F6E\u95EE\u9898\uFF0C\u7528\u8868\u683C\u5448\u73B0\u8C03\u67E5\u7ED3\u679C\u5E76\u7B80\u8981\u5206\u6790\uFF1B\\n4. \u6559\u5B66\u6548\u679C\u603B\u7ED3\uFF1A\u8BF4\u660E\u672C\u5B9E\u9A8C\u5BF9\u5B66\u751F\u80FD\u529B\u57F9\u517B\u7684\u5B9E\u9645\u6548\u679C\uFF0C\u9A8C\u8BC1\u6559\u5B66\u76EE\u6807\u7684\u8FBE\u6210\u60C5\u51B5\u3002\\n\\n### 7. CONCLUSION\uFF08\u7ED3\u8BBA\uFF09\\n\u603B\u7ED3\u8BBA\u6587\u6838\u5FC3\u5185\u5BB9\uFF0C\u7A81\u51FA**\u5B9E\u9A8C\u7684\u79D1\u7814\u4EF7\u503C\u4E0E\u6559\u5B66\u4EF7\u503C**\uFF0C\u907F\u514D\u91CD\u590D\u6458\u8981\u4E0E\u7ED3\u679C\u8BA8\u8BBA\u5185\u5BB9\uFF0C\u8868\u8FF0\u7B80\u6D01\uFF1A\\n1. \u7B80\u8981\u6982\u62EC\u672C\u5B9E\u9A8C\u7684\u6838\u5FC3\u65B9\u6CD5\u3001\u5173\u952E\u7ED3\u679C\u4E0E\u521B\u65B0\u70B9\uFF0C\u9A8C\u8BC1\u5B9E\u9A8C\u7684\u79D1\u5B66\u6027\u4E0E\u53EF\u884C\u6027\uFF1B\\n2. \u603B\u7ED3\u672C\u5B9E\u9A8C\u5728\u672C\u79D1\u5316\u5B66\u6559\u80B2\u4E2D\u7684\u6559\u5B66\u4EF7\u503C\uFF0C\u8BF4\u660E\u5176\u5BF9\u5B66\u751F\u80FD\u529B\u57F9\u517B\u3001\u6559\u5B66\u4F53\u7CFB\u5B8C\u5584\u7684\u610F\u4E49\uFF1B\\n3. \u7B80\u8981\u5C55\u671B\u5B9E\u9A8C\u7684\u4F18\u5316\u65B9\u5411\uFF08\u5982\u53C2\u6570\u8C03\u6574\u3001\u62D3\u5C55\u5B9E\u9A8C\u8BBE\u8BA1\u3001\u6559\u5B66\u65B9\u6CD5\u6539\u8FDB\u7B49\uFF09\uFF0C\u8D34\u5408\u5B9E\u9645\u6559\u5B66\u9700\u6C42\u3002\\n\\n## \u56DB\u3001\u9644\u5C5E\u6A21\u5757\u64B0\u5199\u8981\u6C42\\n### 1. ASSOCIATED CONTENT\uFF08\u76F8\u5173\u5185\u5BB9\uFF09\\n\u6807\u6CE8Supporting Information\uFF08\u8865\u5145\u6750\u6599\uFF09\uFF0C\u660E\u786E\u672C\u8BBA\u6587\u914D\u5957\u7684\u6559\u5B66\u8F85\u52A9\u6750\u6599\uFF0C\u5982**Student Handout\uFF08\u5B66\u751F\u624B\u518C\uFF09\u3001Instructor Notes\uFF08\u6559\u5E08\u6307\u5357\uFF09**\uFF0C\u8BF4\u660E\u6750\u6599\u5305\u542B\u7684\u6838\u5FC3\u5185\u5BB9\uFF08\u5982\u5B9E\u9A8C\u6B65\u9AA4\u7EC6\u5316\u3001\u6559\u5B66\u5B89\u6392\u3001\u9884\u671F\u7ED3\u679C\u3001\u8BC4\u5206\u6807\u51C6\u7B49\uFF09\u3002\\n\\n### 2. AUTHOR INFORMATION\uFF08\u4F5C\u8005\u4FE1\u606F\uFF09\\n\u5206\u4E24\u680F\u64B0\u5199\uFF0C\u4FE1\u606F\u51C6\u786E\u3001\u5B8C\u6574\uFF1A\\n1. Corresponding Authors\uFF1A\u901A\u8BAF\u4F5C\u8005\u59D3\u540D\u3001\u5B8C\u6574\u5355\u4F4D\u3001\u90AE\u7BB1\u5730\u5740\uFF0C\u53EF\u9009ORCID\uFF1B\\n2. Authors\uFF1A\u5176\u4ED6\u4F5C\u8005\u59D3\u540D\u3001\u5B8C\u6574\u5355\u4F4D\uFF0C\u6309\u8D21\u732E\u5EA6\u6392\u5E8F\u3002\\n\\n### 3. ACKNOWLEDGMENTS\uFF08\u81F4\u8C22\uFF09\\n\u7B80\u6D01\u660E\u4E86\uFF0C\u6807\u6CE8\u672C\u5B9E\u9A8C/\u8BBA\u6587\u7684\u8D44\u52A9\u6765\u6E90\uFF08\u5982\u57FA\u91D1\u9879\u76EE\u3001\u6821\u7EA7/\u7701\u7EA7\u6559\u5B66\u6539\u9769\u9879\u76EE\uFF0C\u9700\u6807\u6CE8\u9879\u76EE\u540D\u79F0+\u7F16\u53F7\uFF09\uFF0C\u611F\u8C22\u5B9E\u9A8C\u5BA4\u652F\u6301\u3001\u6559\u5B66\u6307\u5BFC\u4E0E\u5B9E\u9A8C\u534F\u52A9\u4EBA\u5458\uFF08\u53EF\u9009\uFF09\u3002\\n\\n### 4. REFERENCES\uFF08\u53C2\u8003\u6587\u732E\uFF09\\n1. \u6309**\u6B63\u6587\u9996\u6B21\u5F15\u7528\u987A\u5E8F**\u7F16\u53F7\uFF0C\u91C7\u7528ACS\u6570\u5B57\u7F16\u53F7\u683C\u5F0F\uFF0C\u5355\u72EC\u6210\u9875\uFF0C\u6807\u9898\u5168\u5927\u5199\u3001\u52A0\u7C97\uFF1B\\n2. \u53C2\u8003\u6587\u732E\u9700\u6DB5\u76D6**\u5B9E\u9A8C\u76F8\u5173\u7684\u79D1\u7814\u6587\u732E\u3001\u6559\u5B66\u7C7B\u6587\u732E\u3001\u671F\u520A\u683C\u5F0F\u8303\u672C**\uFF0C\u671F\u520A\u540D\u7528ACS\u6807\u51C6\u7F29\u5199\uFF08\u5982J. Chem. Educ.\uFF09\uFF0C\u9875\u7801\u6807\u6CE8\u8D77\u6B62\u8303\u56F4\uFF1B\\n3. \u53C2\u8003\u6587\u732E\u6570\u91CF\u9002\u4E2D\uFF0C\u8D34\u5408\u8BBA\u6587\u4E3B\u9898\uFF0C\u4F18\u5148\u5F15\u7528\u8FD15\u5E74\u7684\u6838\u5FC3\u671F\u520A\u6587\u732E\u4E0E\u672C\u79D1\u6559\u5B66\u76F8\u5173\u6587\u732E\u3002\\n\\n## \u4E94\u3001\u6838\u5FC3\u64B0\u5199\u539F\u5219\\n1. **\u8D34\u5408\u4E3B\u9898**\uFF1A\u6240\u6709\u5185\u5BB9\u7D27\u6263\u4F60\u7684\u8BBA\u6587\u57FA\u672C\u601D\u8DEF\uFF0C\u4E0D\u504F\u79BB\u5B9E\u9A8C\u6838\u5FC3\uFF0C\u65E0\u65E0\u5173\u5185\u5BB9\u5806\u780C\uFF1B\\n2. **\u6559\u5B66\u5C5E\u6027**\uFF1A\u7A81\u51FA\u300AJournal of Chemical Education\u300B\u671F\u520A\u7684\u5316\u5B66\u6559\u80B2\u5B9A\u4F4D\uFF0C\u517C\u987E\u79D1\u7814\u6027\u4E0E\u6559\u5B66\u5B9E\u7528\u6027\uFF0C\u7B26\u5408\u672C\u79D1\u5B9E\u9A8C\u6559\u5B66\u7684\u96BE\u5EA6\u4E0E\u8981\u6C42\uFF1B\\n3. **\u5185\u5BB9\u539F\u521B**\uFF1A\u53C2\u8003\u6750\u6599\u4EC5\u4F5C\u683C\u5F0F\u3001\u6846\u67B6\u4E0E\u8868\u8FF0\u8303\u672C\uFF0C\u4E0D\u5F97\u6284\u88AD\u5185\u5BB9\u3001\u6570\u636E\u4E0E\u56FE\u8868\uFF0C\u5B9E\u9A8C\u6570\u636E\u4E0E\u6559\u5B66\u53CD\u9988\u9700\u8D34\u5408\u5B9E\u9645\uFF1B\\n4. **\u8BED\u8A00\u89C4\u8303**\uFF1A\u91C7\u7528\u6B63\u5F0F\u7684\u82F1\u6587\u79D1\u6280\u8BBA\u6587\u8868\u8FF0\uFF0C\u8BED\u6CD5\u6B63\u786E\u3001\u903B\u8F91\u4E25\u8C28\uFF0C\u65E0\u53E3\u8BED\u5316\u8868\u8FF0\uFF0C\u4E13\u4E1A\u672F\u8BED\u4F7F\u7528\u51C6\u786E\u3001\u7EDF\u4E00\uFF1B\\n5. **\u53EF\u64CD\u4F5C\u6027**\uFF1A\u5B9E\u9A8C\u6D41\u7A0B\u3001\u6559\u5B66\u5B89\u6392\u3001\u64CD\u4F5C\u6B65\u9AA4\u7B49\u5185\u5BB9\u5177\u4F53\u3001\u660E\u786E\uFF0C\u53EF\u76F4\u63A5\u88AB\u672C\u79D1\u9662\u6821\u7528\u4E8E\u76F8\u5173\u5B9E\u9A8C\u6559\u5B66\u3002\\n\\n## \u516D\u3001\u4EA4\u4ED8\u6210\u679C\\n1. \u7B26\u5408\u300AJournal of Chemical Education\u300B\u671F\u520A\u683C\u5F0F\u89C4\u8303\u7684\u5B8C\u6574\u82F1\u6587\u8BBA\u6587\uFF08\u542B\u6807\u9898\u3001\u4F5C\u8005\u4E0E\u5355\u4F4D\u3001\u6458\u8981\u3001\u5173\u952E\u8BCD\u3001\u6B63\u6587\u6240\u6709\u6838\u5FC3\u7AE0\u8282\u3001\u9644\u5C5E\u6A21\u5757\u3001\u53C2\u8003\u6587\u732E\uFF09\uFF1B\\n2. \u8BBA\u6587\u914D\u5957\u7684Supporting Information\u6846\u67B6\uFF08\u542BStudent Handout\u3001Instructor Notes\u6838\u5FC3\u7AE0\u8282\u4E0E\u5185\u5BB9\u8981\u70B9\uFF09\uFF1B\\n3. \u8BBA\u6587\u4E2D\u6D89\u53CA\u7684\u56FE\u8868\u8BBE\u8BA1\u6846\u67B6\uFF08\u542B\u56FE\u8868\u7F16\u53F7\u3001\u6807\u9898\u3001\u6838\u5FC3\u5185\u5BB9\u3001\u6570\u636E\u5448\u73B0\u65B9\u5F0F\uFF09\u3002","owner":"840627088@qq.com","upvotes":2,"downvotes":0,"upvoteDifference":2,"updatedAt":"2026-05-13T06:25:10.901Z"}')}}]);